function adapt(input, solve, kit) {
  const [head] = input;
  const printed = [];
  // Build the list from the back; each node keeps its value and link hidden in a closure.
  let first = null;
  for (let i = head.length - 1; i >= 0; i--) {
    const value = head[i];
    const next = first;
    first = Object.freeze({
      printValue() { printed.push(value); },
      getNext() { return next; },
    });
  }
  solve(first);
  return printed;
}

