function printLinkedListInReverse(head) {
  const stack = [];
  let node = head;

  while (node !== null) {
    stack.push(node);
    node = node.getNext();
  }

  while (stack.length > 0) {
    const top = stack.pop();
    top.printValue();
  }
}

