function printLinkedListInReverse(head) {
  // Constant extra space: count the nodes, then walk from the head to each position, last position first.
  let length = 0;
  for (let cur = head; cur !== null; cur = cur.getNext()) length++;
  for (let target = length - 1; target >= 0; target--) {
    let cur = head;
    for (let step = 0; step < target; step++) cur = cur.getNext();
    cur.printValue();
  }
}

