function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'large') return [Array.from({ length: 1000 }, () => pick(2001) - 1000)];
  const n = 1 + pick(9);
  const roll = rand();
  // Small spans give repeated values; sometimes use the extreme values.
  const span = roll < 0.4 ? 3 : roll < 0.8 ? 50 : 1000;
  return [Array.from({ length: n }, () => pick(2 * span + 1) - span)];
}
